head.script:
scwin.screenId = "jldfil71106";

///////// 1. 변수 및 선언 영역 /////////

scwin.tbh_labels = ["발행증권에 관한 사항","발행증권에 관한 사항2(손실제한)","발행회사에 관한 사항","보증인/제3자LP에 관한 사항","첨부파일"];
scwin.tbh_defaultIndex = 4;

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_tab();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil71106.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////

// 탭 전환 시 breadcrumb 리프를 선택 탭 라벨로 갱신한다.
//   onchange 는 tabControl 이 제공하는 사용자 이벤트다.
/**
 * @event
 * @name scwin.tbh_tabs_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tbh_tabs_onchange = function () {
    var tc = $c.util.getComponent('tbh_tabs');
    if (tc && tc.getSelectedTabIndex) { scwin.tbh_setLeaf(tc.getSelectedTabIndex()); }
};

///////// 4. 서브미션 콜백 영역 /////////

///////// 5. 일반/업무 함수 영역 /////////

// 탭 선택 = 진입 파라미터(tab) > 기본 탭. onpageload 는 엔진 초기화 뒤라 이 시점의 대입이 산다.
/**
 * @method
 * @name scwin.init_tab
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_tab = function () {
    var idx = scwin.tbh_defaultIndex;
    var pd = $c.data.getParameter();
    if (pd && pd.tab !== undefined) { idx = Number(pd.tab); }
    var tc = $c.util.getComponent('tbh_tabs');
    if (!tc || !tc.getSelectedTabIndex) { return; }
    if (tc.getSelectedTabIndex() !== idx) { tc.setSelectedTabIndex(idx); }
    scwin.tbh_setLeaf(idx);
};

/**
 * @method
 * @name scwin.tbh_setLeaf
 * @author Inswave
 * @date 2026. 09. 29
 * @param i
 * @returns
 * @hidden N
*/
scwin.tbh_setLeaf = function (i) {
    var a = $c.util.getComponent('tbh_crumb_leaf');
    if (a && a.setValue) { a.setValue(scwin.tbh_labels[i] || ''); }
};
